import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    props = {}
    p = 2
    for _ in range(m):
        props[(int(data[p]), data[p + 1])] = (data[p + 2], data[p + 3])
        p += 4
    q = int(data[p])
    p += 1
    out = []
    for _ in range(q):
        path = data[p]
        p += 1
        cur, is_obj, val = 0, True, None
        ok = True
        for seg in path.split('.'):
            if not is_obj:
                ok = False
                break
            e = props.get((cur, seg))
            if e is None:
                ok = False
                break
            if e[0] == 'o':
                cur = int(e[1])
            else:
                is_obj = False
                val = int(e[1])
        if not ok:
            out.append('undefined')
        elif is_obj:
            out.append('object')
        else:
            out.append(str(val))
    print('\n'.join(out))

